import { createReadStream } from 'node:fs';

/** Count lines and whitespace-separated words without loading the file into memory. A last line without
 *  a newline still counts. Read in small chunks (highWaterMark: 16) so the tests cross chunk boundaries. */
async function countFile(path: string): Promise<{ lines: number; words: number }> {
  throw new Error('Not implemented');
}

p-count-lines-and-words-in-a-huge-file-w.solution:
import { createReadStream } from 'node:fs';
async function countFile(path: string): Promise<{ lines: number; words: number }> {
  let lines = 0;
  let words = 0;
  let tail = '';
  const decoder = new TextDecoder();
  const countWords = (line: string) => line.split(/\s+/).filter(Boolean).length;
  for await (const chunk of createReadStream(path, { highWaterMark: 16 })) {
    const parts = (tail + decoder.decode(chunk as Buffer, { stream: true })).split('\n');
    tail = parts.pop() ?? '';
    for (const line of parts) {
      lines++;
      words += countWords(line);
    }
  }
  tail += decoder.decode();
  if (tail.length > 0) {
    lines++;
    words += countWords(tail);
  }
  return { lines, words };
}

