import { Transform } from 'node:stream';

/** A Transform that takes string chunks and pushes one parsed object per complete line (object mode out).
 *  Skip blank lines, parse a final line without a newline, and fail the stream on invalid JSON. */
function ndjson(): Transform {
  throw new Error('Not implemented');
}

p-parse-ndjson-from-a-stream-whose-chunk.solution:
import { Transform } from 'node:stream';
function ndjson(): Transform {
  let buffer = '';
  const parse = (line: string, push: (v: unknown) => void) => {
    if (line.trim()) push(JSON.parse(line));
  };
  return new Transform({
    readableObjectMode: true,
    transform(chunk: Buffer | string, _enc, cb) {
      buffer += chunk.toString();
      const lines = buffer.split('\n');
      buffer = lines.pop() ?? '';
      try {
        for (const line of lines) parse(line, (v) => this.push(v));
        cb();
      } catch (err) {
        cb(err as Error);
      }
    },
    flush(cb) {
      try {
        parse(buffer, (v) => this.push(v));
        cb();
      } catch (err) {
        cb(err as Error);
      }
    },
  });
}

