import { Transform } from 'node:stream';

/** An object-mode Transform that emits arrays of `size` records, then a shorter final batch for leftovers
 *  (nothing for empty input). Throw a RangeError for a size below 1. */
function batch<T>(size: number): Transform {
  throw new Error('Not implemented');
}

p-batch-records-into-arrays-of-n.solution:
import { Transform } from 'node:stream';
function batch<T>(size: number): Transform {
  if (!Number.isInteger(size) || size < 1) throw new RangeError('size must be a positive integer');
  let current: T[] = [];
  return new Transform({
    objectMode: true,
    transform(record: T, _enc, cb) {
      current.push(record);
      if (current.length === size) {
        this.push(current);
        current = [];
      }
      cb();
    },
    flush(cb) {
      if (current.length > 0) this.push(current);
      cb();
    },
  });
}

