import { pipeline } from 'node:stream/promises';

/** Handle GET /relay?count=N: stream `${upstreamUrl}/?count=N` to the client as text/event-stream, with
 *  backpressure. When the client disconnects early, abort the upstream request. Answer 502 if the upstream
 *  fails before any data was sent. */
async function relay(req: IncomingMessage, res: ServerResponse, upstreamUrl: string): Promise<void> {
  throw new Error('Not implemented');
}

p-relay-an-upstream-event-stream-and-can.solution:
import type { IncomingMessage, ServerResponse } from 'node:http';
import { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
async function relay(req: IncomingMessage, res: ServerResponse, upstreamUrl: string): Promise<void> {
  const count = new URL(req.url ?? '/', 'http://x').searchParams.get('count') ?? '3';
  const controller = new AbortController();
  res.on('close', () => {
    if (!res.writableEnded) controller.abort();
  });
  try {
    const up = await fetch(`${upstreamUrl}/?count=${count}`, { signal: controller.signal });
    if (!up.ok || !up.body) throw new Error(`upstream ${up.status}`);
    res.writeHead(200, { 'content-type': 'text/event-stream', 'cache-control': 'no-cache', 'x-accel-buffering': 'no' });
    await pipeline(Readable.fromWeb(up.body as import('node:stream/web').ReadableStream<Uint8Array>), res, { signal: controller.signal });
  } catch {
    if (!res.headersSent) res.writeHead(502).end();
    else res.destroy();
  }
}

