    await pipeline(Readable.fromWeb(up.body as import('node:stream/web').ReadableStream<Uint8Array>), res, { signal: controller.signal });
  } catch {
    if (!res.headersSent) res.writeHead(502).end();
    else res.destroy();
  }
});
